@@ -19,6 +19,9 @@ const runtimeCommandWaitDelay = 100 * time.Millisecond

 var runtimeCommandJobs sync.Map

+// Diagnostic observer only; this isolated historical checkout must not be merged.
+var windowsStartupInvestigationResume func(uint32, uint32, uint32, error)
+
 type jobBasicAccountingInformation struct {
 	totalUserTime             int64
 	totalKernelTime           int64
@@ -113,8 +116,11 @@ func resumeCommandPrimaryThread(processID uint32) error {
 			return openErr
 		}
 		defer win.CloseHandle(thread)
-		_, err = win.ResumeThread(thread)
-		return err
+		previousSuspendCount, resumeErr := win.ResumeThread(thread)
+		if windowsStartupInvestigationResume != nil {
+			windowsStartupInvestigationResume(processID, entry.ThreadID, previousSuspendCount, resumeErr)
+		}
+		return resumeErr
 	}
 	return fmt.Errorf("find suspended primary thread for process %d: %w", processID, err)
 }
