diff --git a/internal/runtime/windows_startup_investigation_test.go b/internal/runtime/windows_startup_investigation_test.go
new file mode 100644
index 00000000..d862de1b
--- /dev/null
+++ b/internal/runtime/windows_startup_investigation_test.go
@@ -0,0 +1,193 @@
+//go:build windows
+
+package runtime
+
+import (
+	"bytes"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"os"
+	"os/exec"
+	"sync"
+	"testing"
+	"time"
+	"unsafe"
+
+	win "golang.org/x/sys/windows"
+)
+
+type windowsStartupBuffer struct {
+	mu   sync.Mutex
+	data bytes.Buffer
+}
+
+func (b *windowsStartupBuffer) Write(p []byte) (int, error) {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+	return b.data.Write(p)
+}
+func (b *windowsStartupBuffer) snapshot() string {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+	return b.data.String()
+}
+
+type windowsResumeObservation struct {
+	ProcessID            uint32 `json:"process_id"`
+	ThreadID             uint32 `json:"thread_id"`
+	PreviousSuspendCount uint32 `json:"previous_suspend_count"`
+	Error                string `json:"error,omitempty"`
+	SinceStart           string `json:"since_start"`
+}
+type windowsStartupInvestigation struct {
+	stdout, stderr windowsStartupBuffer
+	started        time.Time
+	resumes        []windowsResumeObservation
+	captured       bool
+}
+
+func newWindowsStartupInvestigation(t *testing.T) *windowsStartupInvestigation {
+	t.Helper()
+	d := &windowsStartupInvestigation{}
+	previous := windowsStartupInvestigationResume
+	windowsStartupInvestigationResume = func(pid, tid, count uint32, err error) {
+		e := ""
+		if err != nil {
+			e = err.Error()
+		}
+		d.resumes = append(d.resumes, windowsResumeObservation{pid, tid, count, e, time.Since(d.started).String()})
+	}
+	t.Cleanup(func() { windowsStartupInvestigationResume = previous })
+	return d
+}
+func (d *windowsStartupInvestigation) captureFailureBeforeCancel(t *testing.T, cmd *exec.Cmd, marker string) {
+	t.Helper()
+	if !d.captured {
+		d.capture(t, cmd, marker, "failure-before-original-cancel-defer")
+	}
+}
+func (d *windowsStartupInvestigation) capture(t *testing.T, cmd *exec.Cmd, marker, phase string) {
+	t.Helper()
+	d.captured = true
+	event := map[string]any{"phase": phase, "elapsed": time.Since(d.started).String(), "utc": time.Now().UTC().Format(time.RFC3339Nano), "command_path": cmd.Path, "command_args": cmd.Args, "resume_observations": d.resumes, "stdout": d.stdout.snapshot(), "stderr": d.stderr.snapshot(), "test_failed_before_capture": t.Failed()}
+	if b, err := os.ReadFile(marker); err == nil {
+		event["marker_bytes"] = string(b)
+	} else {
+		event["marker_read_error"] = err.Error()
+	}
+	if cmd.Process != nil {
+		pid := uint32(cmd.Process.Pid)
+		event["parent_pid"] = pid
+		handle, err := win.OpenProcess(win.SYNCHRONIZE|win.PROCESS_QUERY_LIMITED_INFORMATION, false, pid)
+		if err != nil {
+			event["open_parent_error"] = err.Error()
+		} else {
+			status, waitErr := win.WaitForSingleObject(handle, 0)
+			event["parent_wait_status"] = status
+			if waitErr != nil {
+				event["parent_wait_error"] = waitErr.Error()
+			}
+			var code uint32
+			err = win.GetExitCodeProcess(handle, &code)
+			event["parent_exit_code"] = code
+			if err != nil {
+				event["parent_exit_error"] = err.Error()
+			}
+			_ = win.CloseHandle(handle)
+		}
+		event["parent_threads"] = windowsStartupThreads(pid)
+		event["descendants"] = windowsStartupDescendants(pid)
+	}
+	if job, ok := runtimeCommandJobs.Load(cmd); ok {
+		var info jobBasicAccountingInformation
+		err := win.QueryInformationJobObject(job.(win.Handle), win.JobObjectBasicAccountingInformation, uintptr(unsafe.Pointer(&info)), uint32(unsafe.Sizeof(info)), nil)
+		if err != nil {
+			event["job_query_error"] = err.Error()
+		} else {
+			event["job_active_processes"] = info.activeProcesses
+			event["job_total_processes"] = info.totalProcesses
+			event["job_terminated_processes"] = info.totalTerminatedProcesses
+		}
+	}
+	b, err := json.Marshal(event)
+	if err != nil {
+		t.Errorf("marshal original startup diagnostic: %v", err)
+		return
+	}
+	t.Logf("WINDOWS_STARTUP_DIAGNOSTIC %s", b)
+}
+func (d *windowsStartupInvestigation) captureFinalOutput(t *testing.T, cmd *exec.Cmd) {
+	t.Helper()
+	event := map[string]any{"phase": "final-output-after-original-deferred-cleanup", "elapsed": time.Since(d.started).String(), "stdout": d.stdout.snapshot(), "stderr": d.stderr.snapshot()}
+	if cmd.ProcessState != nil {
+		event["process_state"] = cmd.ProcessState.String()
+		event["exit_code"] = cmd.ProcessState.ExitCode()
+	} else {
+		event["process_state"] = "unavailable"
+	}
+	b, err := json.Marshal(event)
+	if err != nil {
+		t.Errorf("marshal final startup output: %v", err)
+		return
+	}
+	t.Logf("WINDOWS_STARTUP_DIAGNOSTIC %s", b)
+}
+func windowsStartupThreads(pid uint32) any {
+	snapshot, err := win.CreateToolhelp32Snapshot(win.TH32CS_SNAPTHREAD, 0)
+	if err != nil {
+		return map[string]string{"error": err.Error()}
+	}
+	defer win.CloseHandle(snapshot)
+	entry := win.ThreadEntry32{Size: uint32(unsafe.Sizeof(win.ThreadEntry32{}))}
+	ids := []uint32{}
+	scanned := 0
+	for err = win.Thread32First(snapshot, &entry); err == nil; err = win.Thread32Next(snapshot, &entry) {
+		scanned++
+		if scanned > 65536 {
+			return map[string]any{"ids": ids, "truncated": true}
+		}
+		if entry.OwnerProcessID == pid {
+			ids = append(ids, entry.ThreadID)
+		}
+	}
+	if err != nil && !errors.Is(err, win.ERROR_NO_MORE_FILES) {
+		return map[string]any{"ids": ids, "enumeration_error": err.Error(), "complete": false}
+	}
+	return map[string]any{"ids": ids, "complete": true}
+}
+func windowsStartupDescendants(pid uint32) any {
+	snapshot, err := win.CreateToolhelp32Snapshot(win.TH32CS_SNAPPROCESS, 0)
+	if err != nil {
+		return map[string]string{"error": err.Error()}
+	}
+	defer win.CloseHandle(snapshot)
+	entry := win.ProcessEntry32{Size: uint32(unsafe.Sizeof(win.ProcessEntry32{}))}
+	all := []win.ProcessEntry32{}
+	for err = win.Process32First(snapshot, &entry); err == nil; err = win.Process32Next(snapshot, &entry) {
+		all = append(all, entry)
+		if len(all) > 65536 {
+			return map[string]string{"error": "process inventory limit"}
+		}
+	}
+	enumerationError := ""
+	if err != nil && !errors.Is(err, win.ERROR_NO_MORE_FILES) {
+		enumerationError = err.Error()
+	}
+	selected := map[uint32]bool{pid: true}
+	result := []map[string]any{}
+	for pass := 0; pass < 16; pass++ {
+		added := false
+		for _, p := range all {
+			if !selected[p.ProcessID] && selected[p.ParentProcessID] {
+				selected[p.ProcessID] = true
+				result = append(result, map[string]any{"pid": p.ProcessID, "parent_pid": p.ParentProcessID, "exe": win.UTF16ToString(p.ExeFile[:]), "threads": p.Threads})
+				added = true
+			}
+		}
+		if !added {
+			return map[string]any{"processes": result, "enumeration_error": enumerationError, "complete": enumerationError == ""}
+		}
+	}
+	return map[string]any{"processes": result, "error": fmt.Sprint("descendant depth limit")}
+}
